# region: shape
def shape(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: emit
def emit(xs):
    return [v for v in xs if v % 2 == 0]

# region: render
def render(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: intake
def intake(xs):
    return [v for v in xs if v % 2 == 0]

# region: digest
def digest(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: gather
def gather(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) > bar else 'low'
    return out

# region: run
def run(raw):
    return gather(digest(intake(render(emit(shape(raw))))))

